# APRON numerical abstract domains: the C libraries (libapron.a and every
# domain: box, octagons, newpolka, taylor1plus, avoct, PPL's polyhedra and
# grids with the polkaGrid product, PPLite's polyhedra, fppol on GLPK) and
# the OCaml stubs generated by camlidl (libapron_caml.a,
# lib<domain><num>_caml.a).  Every domain is built, whichever the host's
# apron has (its OCaml side decides which a program can use).
#
# wasm has no FPU rounding-mode control: ap_fpu_init fails and the box/oct
# managers print a warning when allocated.  The exact (MPQ) domains are not
# affected; the double (D) ones round to nearest.

SOURCE=opam:apron
DEPENDS="mlgmpidl camlidl gmp mpfr ppl pplite flint glpk"

# <directory>:<OCaml stubs>:<C libraries lib<x><num>.a>:<what they need>
APRON_DOMAINS="box:box:box: octagons:oct:oct: newpolka:polka:polka: taylor1plus:t1p:t1p: avoct:avo:avo:
ppl:ap_ppl:ap_ppl:-lppl,-lgmpxx,-sDEFAULT_TO_CXX=1
products:polkaGrid:ap_pkgrid:-lpolkaMPQ,-lap_ppl,-lppl,-lgmpxx,-sDEFAULT_TO_CXX=1
pplite:ap_pplite:ap_pplite:-lpplite,-lflint,-lgmpxx,-sDEFAULT_TO_CXX=1 fppol:fpp:fpp:-lglpk"

build() {
  # objects of the native build, when the sources are opam's build directory
  find . \( -name '*.o' -o -name '*.a' -o -name '*.so' \) -delete
  GMP_PREFIX=$SYSROOT MPFR_PREFIX=$SYSROOT PPL_PREFIX=$SYSROOT PPLITE_PREFIX=$SYSROOT \
    FLINT_PREFIX=$SYSROOT GLPK_PREFIX=$SYSROOT emconfigure ./configure -prefix "$SYSROOT" \
    -no-ocaml -no-java -no-strip >&2
  local m
  for m in HAS_CPP HAS_PPL HAS_PPLITE HAS_GLPK; do
    grep -q "^$m = 1" Makefile.config || die "configure did not find what $m needs"
  done
  # C libraries, static only
  local cflags="$CFLAGS -U__STRICT_ANSI__ -std=c99 -I$SYSROOT/include"
  local cxxflags="$CXXFLAGS -U__STRICT_ANSI__ -I$SYSROOT/include"
  emmake make c HAS_SHARED= CC="$EMCC" CXX="$EMSDK_BIN/em++" AR="$EMAR" RANLIB=true \
    CFLAGS="$cflags -DNDEBUG" CFLAGS_DEBUG="$cflags" CXXFLAGS="$cxxflags -DNDEBUG" CXXFLAGS_DEBUG="$cxxflags" \
    PPLITE_CXXFLAGS="$cxxflags -std=c++17 -DNDEBUG" PPLITE_CXXFLAGS_DEBUG="$cxxflags -std=c++17" -j"$NPROC" >&2
  local a
  while IFS= read -r a; do install_lib "$a"; provides apron "$(basename "$a" .a | sed 's/^lib//')"
  done < <(find . -name 'lib*.a' ! -name '*_debug.a' ! -path './japron/*')
  install_headers apron apron/*.h num/*.h itv/*.h mlapronidl/apron_caml.h

  # OCaml stubs: the camlidl output is in the opam build directory, or is
  # regenerated with the host camlidl.  -std=c99 as in apron's own build: its
  # headers define bool, a keyword since C23.
  local inc="-std=c99 -Iapron -Inum -Iitv -Imlapronidl" objs= ent dir pre clib needs lib num
  local idl
  idl=$(make_var mlapronidl IDLMODULES)
  for m in $idl; do
    [ -f "mlapronidl/${m}_caml.c" ] || make -C mlapronidl "${m}_caml.c" \
      CAMLIDL="$HOST_BIN/camlidl" PERL=perl MLGMPIDL_PREFIX="$SYSROOT" >&2
  done
  for m in mlapronidl/*_caml.c; do
    # shellcheck disable=SC2086
    stub_cc "$m" $inc; objs="$objs ${m%.c}.o"
  done
  # shellcheck disable=SC2086
  mklib apron_caml $objs
  install_lib libapron_caml.a
  link_flags apron_caml "-lapron -lmpfr -lgmp"
  provides apron apron_caml
  for ent in $APRON_DOMAINS; do
    IFS=: read -r dir pre clib needs <<< "$ent"
    [ -f "$dir/${pre}_caml.c" ] || make -C "$dir" "${pre}_caml.c" \
      CAMLIDL="$HOST_BIN/camlidl" PERL=perl MLGMPIDL_PREFIX="$SYSROOT" >&2
    # (polkaGrid's stubs include polka's and PPL's headers)
    # shellcheck disable=SC2086
    stub_cc "$dir/${pre}_caml.c" $inc -I"$dir" -Inewpolka -Ippl
    # one stub object for every numeric variant of the domain's C library
    for lib in "$dir"/lib"$clib"*.a; do
      lib=$(basename "$lib" .a); lib=${lib#lib}
      case $lib in *_debug|*_caml) continue ;; esac
      num=${lib#"$clib"}
      ( cd "$dir" && mklib "$pre${num}_caml" "${pre}_caml.o" )
      install_lib "$dir/lib$pre${num}_caml.a"
      link_flags "$pre${num}_caml" "-l$lib ${needs//,/ } -lapron -lmpfr -lgmp"
      provides apron "$pre${num}_caml"
    done
  done
}
